  -- END GENERATED CUSTODES MFM PAYLOAD
  v_item jsonb;
  v_option jsonb;
  v_faction_id uuid;
  v_template_id uuid;
  v_technology_id uuid;
begin
  select id into v_faction_id from public.factions where slug = 'adeptus-custodes';
  if v_faction_id is null then
    return;
  end if;

  if jsonb_array_length(v_items) <> 29 then
    raise exception 'El catalogo MFM de Custodes debe tener 29 fichas';
  end if;

  for v_item in select value from jsonb_array_elements(v_items) loop
    select id into v_technology_id
    from public.technology_nodes
    where slug = v_item->>'technologyNodeSlug';
    if v_technology_id is null then
      raise exception 'Falta tecnologia para %', v_item->>'slug';
    end if;

    v_template_id := public.seed_uuid('unit_template', v_item->>'slug');
    insert into public.unit_templates (
      id, slug, faction_id, name, category, unit_type, unit_keywords,
      points, default_quantity, wounds_per_model,
      supply_cost, minerals_cost, ancestral_stone_cost, honor_cost, gold_cost,
      industrial_material_cost, uridium_cost, technology_cost,
      recruitment_time_seconds, recruitment_building_type, notes,
      is_available, required_technology_node_id, source_section,
      source_faction_name, is_allied_unit
    ) values (
      v_template_id, v_item->>'slug', v_faction_id, v_item->>'name',
      v_item->>'category', v_item->>'unitType',
      array(select jsonb_array_elements_text(v_item->'unitKeywords')),
      (v_item->>'points')::integer, (v_item->>'defaultQuantity')::integer,
      (v_item->>'woundsPerModel')::integer,
      (v_item->>'supplyCost')::integer, (v_item->>'mineralsCost')::integer,
      0, (v_item->>'honorCost')::integer, (v_item->>'goldCost')::integer,
      0, 0, 0, (v_item->>'recruitmentTimeSeconds')::integer,
      v_item->>'recruitmentBuildingType', 'Puntos MFM 11th edition.',
      true, v_technology_id, 'MFM 11th edition', 'Imperium - Adeptus Custodes', false
    )
    on conflict (slug) do update set
      name = excluded.name,
      category = excluded.category,
      unit_type = excluded.unit_type,
      unit_keywords = excluded.unit_keywords,
      points = excluded.points,
      default_quantity = excluded.default_quantity,
      wounds_per_model = excluded.wounds_per_model,
      supply_cost = excluded.supply_cost,
      minerals_cost = excluded.minerals_cost,
      honor_cost = excluded.honor_cost,
      gold_cost = excluded.gold_cost,
      recruitment_time_seconds = excluded.recruitment_time_seconds,
      recruitment_building_type = excluded.recruitment_building_type,
      is_available = true,
      required_technology_node_id = excluded.required_technology_node_id,
      source_section = excluded.source_section,
      source_faction_name = excluded.source_faction_name,
      is_allied_unit = false;

    insert into public.unit_template_technology_unlocks (unit_template_id, technology_node_id)
    values (v_template_id, v_technology_id)
    on conflict do nothing;

    for v_option in select value from jsonb_array_elements(v_item->'models') loop
      insert into public.unit_template_model_options (
        id, unit_template_id, slug, label, models, min_models, max_models,
        points, copy_from, copy_to, source, points_change_direction,
        points_change_amount
      ) values (
        public.seed_uuid('unit_template_model_option', (v_item->>'slug') || ':' || (v_option->>'slug')),
        v_template_id, v_option->>'slug', v_option->>'label',
        (v_option->>'models')::integer, (v_option->>'minModels')::integer,
        (v_option->>'maxModels')::integer, (v_option->>'points')::integer,
        (v_option->>'copyFrom')::integer, (v_option->>'copyTo')::integer,
        'mfm', v_option->>'changeDirection', (v_option->>'changeAmount')::integer
      )
      on conflict (unit_template_id, slug) do update set
        label = excluded.label, models = excluded.models,
        min_models = excluded.min_models, max_models = excluded.max_models,
        points = excluded.points, copy_from = excluded.copy_from,
        copy_to = excluded.copy_to, source = excluded.source,
        points_change_direction = excluded.points_change_direction,
        points_change_amount = excluded.points_change_amount,
        updated_at = now();
    end loop;

    for v_option in select value from jsonb_array_elements(v_item->'wargear') loop
      insert into public.unit_template_wargear_options (
        id, unit_template_id, slug, name, points, pricing, source,
        points_change_direction, points_change_amount
      ) values (
        public.seed_uuid('unit_template_wargear_option', (v_item->>'slug') || ':' || (v_option->>'slug')),
        v_template_id, v_option->>'slug', v_option->>'name',
        (v_option->>'points')::integer, v_option->>'pricing', 'mfm',
        v_option->>'changeDirection', (v_option->>'changeAmount')::integer
      )
      on conflict (unit_template_id, slug) do update set
        name = excluded.name, points = excluded.points,
        pricing = excluded.pricing, source = excluded.source,
        points_change_direction = excluded.points_change_direction,
        points_change_amount = excluded.points_change_amount,
        updated_at = now();
    end loop;

    update public.campaign_units
    set selected_model_option_id = null
    where selected_model_option_id in (
      select option.id from public.unit_template_model_options as option
      where option.unit_template_id = v_template_id
        and not exists (
          select 1 from jsonb_array_elements(v_item->'models') as listed(value)
          where listed.value->>'slug' = option.slug
        )
    );
    update public.recruitment_queue
    set selected_model_option_id = null
    where selected_model_option_id in (
      select option.id from public.unit_template_model_options as option
      where option.unit_template_id = v_template_id
        and not exists (
          select 1 from jsonb_array_elements(v_item->'models') as listed(value)
          where listed.value->>'slug' = option.slug
        )
    );
    delete from public.unit_template_model_options as option
    where option.unit_template_id = v_template_id
      and not exists (
        select 1 from jsonb_array_elements(v_item->'models') as listed(value)
        where listed.value->>'slug' = option.slug
      );
    delete from public.unit_template_wargear_options as option
    where option.unit_template_id = v_template_id
      and not exists (
        select 1 from jsonb_array_elements(v_item->'wargear') as listed(value)
        where listed.value->>'slug' = option.slug
      );
  end loop;

  update public.unit_templates
  set is_available = false
  where faction_id = v_faction_id
    and is_allied_unit = false
    and name not like '%[Crucible]%'
    and slug not in (
      select item.value->>'slug' from jsonb_array_elements(v_items) as item(value)
    );
end $$;

