  v_nodes jsonb := $nodes$[{"slug":"custodes-custodia-auramita","description":"La guardia basica del Trono forma la primera linea de defensa perfecta y ofensiva disciplinada. Desbloquea: Custodian Guard Sodality.","effectSummary":"Desbloquea: Custodian Guard Sodality.","unitTemplateSlugs":["unit-adeptus-custodes-custodian-guard-sodality"]},{"slug":"custodes-lanzas-especialistas","description":"Las formaciones de guardianes se diversifican en escoltas y armas especializadas de auramita. Desbloquea: Custodian Wardens y Sentinel Guard Sodality.","effectSummary":"Desbloquea: Custodian Wardens y Sentinel Guard Sodality.","unitTemplateSlugs":["unit-adeptus-custodes-custodian-wardens","unit-adeptus-custodes-sentinel-guard-sodality"]},{"slug":"custodes-campeones-escudo","description":"El mando individual del Adeptus Custodes despliega duelistas y capitanes de autoridad excepcional. Desbloquea: Blade Champion, Shield-Captain y Guardian of the Throne [Crucible].","effectSummary":"Desbloquea: Blade Champion, Shield-Captain y Guardian of the Throne [Crucible].","unitTemplateSlugs":["unit-adeptus-custodes-blade-champion","unit-adeptus-custodes-shield-captain","unit-adeptus-custodes-guardian-of-the-throne-crucible"]},{"slug":"custodes-terminadores-auricos","description":"Las armaduras mas pesadas de la Guardia avanzan contra objetivos imposibles. Desbloquea: Allarus Custodians, Aquilon Terminators with Solarite Power Gauntlets, Aquilon Terminators with Solarite Power Talons y Shield-Captain in Allarus Terminator Armour.","effectSummary":"Desbloquea: Allarus Custodians, Aquilon Terminators with Solarite Power Gauntlets, Aquilon Terminators with Solarite Power Talons y Shield-Captain in Allarus Terminator Armour.","unitTemplateSlugs":["unit-adeptus-custodes-allarus-custodians","unit-adeptus-custodes-aquilon-terminators-with-solarite-power-gauntlets","unit-adeptus-custodes-aquilon-terminators-with-solarite-power-talons","unit-adeptus-custodes-shield-captain-in-allarus-terminator-armour"]},{"slug":"custodes-hueste-victoria","description":"La elite movil y los heroes mayores del Trono transforman cualquier frente en un juramento cumplido. Desbloquea: Trajann Valoris, Venatari with Kinetic Destroyers, Venatari with Verutum Lances, Vertus Praetors, Gyrfalcon Jetbike Sodality, Kataphraktoi Exemplar [Crucible] y Shield-Captain on Dawneagle Jetbike.","effectSummary":"Desbloquea: Trajann Valoris, Venatari with Kinetic Destroyers, Venatari with Verutum Lances, Vertus Praetors, Gyrfalcon Jetbike Sodality, Kataphraktoi Exemplar [Crucible] y Shield-Captain on Dawneagle Jetbike.","unitTemplateSlugs":["unit-adeptus-custodes-trajann-valoris","unit-adeptus-custodes-venatari-with-kinetic-destroyers","unit-adeptus-custodes-venatari-with-verutum-lances","unit-adeptus-custodes-vertus-praetors","unit-adeptus-custodes-gyrfalcon-jetbike-sodality","unit-adeptus-custodes-kataphraktoi-exemplar-crucible","unit-adeptus-custodes-shield-captain-on-dawneagle-jetbike"]},{"slug":"custodes-escuadras-nulas","description":"Las Hermanas del Silencio sellan rutas psiquicas y cazan brujas. Desbloquea: Prosecutor Squad, Vigilator Squad y Witchseeker Squad.","effectSummary":"Desbloquea: Prosecutor Squad, Vigilator Squad y Witchseeker Squad.","unitTemplateSlugs":["unit-adeptus-custodes-prosecutor-squad","unit-adeptus-custodes-vigilator-squad","unit-adeptus-custodes-witchseeker-squad"]},{"slug":"custodes-centuras-vigilia","description":"La cadena de mando Anathema despliega ejecutoras y protocolos [Crucible]. Desbloquea: Knight-Centura y Null Maiden [Crucible].","effectSummary":"Desbloquea: Knight-Centura y Null Maiden [Crucible].","unitTemplateSlugs":["unit-adeptus-custodes-knight-centura","unit-adeptus-custodes-null-maiden-crucible"]},{"slug":"custodes-rhino-psykana","description":"Transportes sellados permiten que las cazadoras nulas lleguen a santuarios, frentes y brechas psiquicas. Desbloquea: Anathema Psykana Rhino.","effectSummary":"Desbloquea: Anathema Psykana Rhino.","unitTemplateSlugs":["unit-adeptus-custodes-anathema-psykana-rhino"]},{"slug":"custodes-procesion-juramentada","description":"Auxiliares imperiales autorizados acompanan a la Camara como voz ritual, testigo y penitencia armada. Desbloquea: Ministorum Priest.","effectSummary":"Desbloquea: Ministorum Priest.","unitTemplateSlugs":["unit-adeptus-custodes-ministorum-priest"]},{"slug":"custodes-grav-ligero","description":"Los primeros chasis grav aseguran rutas, evacuaciones tacticas y golpes quirurgicos en la frontera. Desbloquea: Pallas Grav-attack y Coronus Grav-carrier.","effectSummary":"Desbloquea: Pallas Grav-attack, Coronus Grav-carrier.","unitTemplateSlugs":["unit-adeptus-custodes-pallas-grav-attack","unit-adeptus-custodes-coronus-grav-carrier"]},{"slug":"custodes-sarcofagos-venerables","description":"Los heroes caidos del Trono vuelven a caminar en chasis Contemptor para duelos y brechas. Desbloquea: Contemptor-Achillus Dreadnought y Contemptor-Galatus Dreadnought.","effectSummary":"Desbloquea: Contemptor-Achillus Dreadnought y Contemptor-Galatus Dreadnought.","unitTemplateSlugs":["unit-adeptus-custodes-contemptor-achillus-dreadnought","unit-adeptus-custodes-contemptor-galatus-dreadnought"]},{"slug":"custodes-blindados-auramita","description":"Tanques grav y dreadnoughts pesados forman la respuesta dorada a una guerra total. Desbloquea: Caladius Grav-tank, Caladius Annihilator Grav-tank y Telemon Heavy Dreadnought.","effectSummary":"Desbloquea: Caladius Grav-tank, Caladius Annihilator Grav-tank y Telemon Heavy Dreadnought.","unitTemplateSlugs":["unit-adeptus-custodes-caladius-grav-tank","unit-adeptus-custodes-caladius-annihilator-grav-tank","unit-adeptus-custodes-telemon-heavy-dreadnought"]},{"slug":"custodes-naves-trono","description":"Aeronaves de asalto y supremacia orbital permiten llevar la guerra del Trono a cualquier mundo rebelde. Desbloquea: Ares Gunship y Orion Assault Dropship.","effectSummary":"Desbloquea: Ares Gunship, Orion Assault Dropship.","unitTemplateSlugs":["unit-adeptus-custodes-ares-gunship","unit-adeptus-custodes-orion-assault-dropship"]},{"slug":"custodes-casas-questoris","description":"Juramentos de sangre y deuda abren el apoyo de Armigers, Barones y Knights aliados para guerras que superan una guarnicion. Desbloquea: Armiger Helverin, Armiger Warglaive, Armiger Moirax, Knight Destrier, Knight Gallant, Knight Preceptor, Knight Paladin, Knight Warden, Knight Crusader, Knight Defender, Knight Castellan, Knight Valiant, Cerastus Knight Lancer y Canis Rex.","effectSummary":"Desbloquea: Armiger Helverin, Armiger Warglaive, Armiger Moirax, Knight Destrier, Knight Gallant, Knight Preceptor, Knight Paladin, Knight Warden, Knight Crusader, Knight Defender, Knight Castellan, Knight Valiant, Cerastus Knight Lancer, Canis Rex.","unitTemplateSlugs":["unit-adeptus-custodes-armiger-helverin","unit-adeptus-custodes-armiger-warglaive","unit-adeptus-custodes-armiger-moirax","unit-adeptus-custodes-knight-destrier","unit-adeptus-custodes-knight-gallant","unit-adeptus-custodes-knight-preceptor","unit-adeptus-custodes-knight-paladin","unit-adeptus-custodes-knight-warden","unit-adeptus-custodes-knight-crusader","unit-adeptus-custodes-knight-defender","unit-adeptus-custodes-knight-castellan","unit-adeptus-custodes-knight-valiant","unit-adeptus-custodes-cerastus-knight-lancer","unit-adeptus-custodes-canis-rex"]},{"slug":"custodes-titanes-terra","description":"Los pactos mas extremos movilizan Acastus, maquinas dios y Titanes como simbolos absolutos de intervencion imperial. Desbloquea: Acastus Knight Porphyrion, Acastus Knight Asterius, Warhound Titan y Warlord Titan.","effectSummary":"Desbloquea: Acastus Knight Porphyrion, Acastus Knight Asterius, Warhound Titan, Warlord Titan.","unitTemplateSlugs":["unit-adeptus-custodes-acastus-knight-porphyrion","unit-adeptus-custodes-acastus-knight-asterius","unit-adeptus-custodes-warhound-titan","unit-adeptus-custodes-warlord-titan"]}]$nodes$::jsonb;
  -- END GENERATED CUSTODES TECH PAYLOAD
  v_node jsonb;
begin
  if jsonb_array_length(v_nodes) <> 15 then
    raise exception 'El arbol Custodes debe mantener sus 15 nodos';
  end if;
  for v_node in select value from jsonb_array_elements(v_nodes) loop
    update public.technology_nodes
    set description = v_node->>'description',
        effect_summary = v_node->>'effectSummary'
    where slug = v_node->>'slug'
      and tree_key = 'troops-adeptus-custodes-v1';
    if not found then
      raise exception 'Falta nodo Custodes %', v_node->>'slug';
    end if;
    update public.technology_effects
    set payload = jsonb_build_object('unit_template_slugs', v_node->'unitTemplateSlugs')
    where technology_node_id = (
      select id from public.technology_nodes where slug = v_node->>'slug'
    ) and effect_type = 'unlock_unit_template';
